import{_ as e,o as a,c as r,a2 as o}from"./chunks/framework.hw3Av5Vn.js";const s="/llamatron/assets/strum_editor.gJJ6bToK.svg",g=JSON.parse('{"title":"Strum","description":"","frontmatter":{},"headers":[],"relativePath":"generators/STRUM.md","filePath":"generators/STRUM.md"}'),n={name:"generators/STRUM.md"};function h(i,t,d,c,l,p){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="strum" tabindex="-1">Strum <a class="header-anchor" href="#strum" aria-label="Permalink to &quot;Strum&quot;">​</a></h1><p>A keyboard plays a chord&#39;s notes all at once; a guitarist&#39;s pick crosses the strings one after another, low to high on a downstroke and high to low on an upstroke. Strum plays chords that way, each note still ending where the chord ends. Strum changes only when the notes start, as a groove does, so every export and real-time playback hear it.</p><p>Strum can be set in three places: in the track editor&#39;s <code>+ Strum</code> section, for every clip on the track; in the clip page&#39;s <code>+ Strum</code> section, for one clip, which wins over the track&#39;s; and as a Strum generator in a chain, which wins over both.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p><img src="'+s+'" alt="A Strum generator&#39;s settings"></p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td>Direction</td><td>&quot;by the beat&quot;, down on the beats and up between them, as a hand that never stops moving does; &quot;down&quot;, every chord low to high; &quot;up&quot;, every chord high to low, the reggae skank; &quot;down up&quot;, alternating chord by chord; or &quot;off&quot;, for a clip that won&#39;t take its track&#39;s strum. A new Strum generator strums by the beat.</td></tr><tr><td>Spread</td><td>How far apart two strings sound, in milliseconds whatever the tempo, since a hand doesn&#39;t slow down with the song: tight (2 ms), crisp (4), normal (8, the default), loose (15), rake (30) or harp (70), where each note of a roll is heard.</td></tr><tr><td>Fade</td><td>How much quieter the last string is than the first, up to 50%.</td></tr><tr><td>Loose timing</td><td>How much each gap between strings varies, up to 50%, as a real hand does, drawn from the song&#39;s seed.</td></tr><tr><td>Upstroke strings</td><td>What an upstroke catches: all the notes, or only the top 3 or the top 4, so that up-strums sound lighter.</td></tr><tr><td>Restart</td><td>On the generator, when it starts over, as <a href="./../GENERATORS#restart">Generators</a> describes.</td></tr></tbody></table><h2 id="applying-the-generator" tabindex="-1">Applying the Generator <a class="header-anchor" href="#applying-the-generator" aria-label="Permalink to &quot;Applying the Generator&quot;">​</a></h2><p>Set Strum on a track or a clip, or add a Strum generator to a chain, as <code>strum: name</code>, and give clips that chain. <code>examples/learning/13_classic_strum.yml</code> is an acoustic folk song that compares the spreads.</p>',8)])])}const m=e(n,[["render",h]]);export{g as __pageData,m as default};
